UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Infectologia / Antimicrobiano","pharmacological_class":"Macrolídeo","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"500 mg","interval_text":"24/24 horas (azitromicina) ou 12/12 horas (claritromicina)","route":"Via oral","duration_text":"3 a 5 dias (azitromicina) ou 7 a 14 dias (claritromicina)","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita de Controle Especial (Antimicrobianos - 2 vias)"}],"contraindications":["Hipersensibilidade a macrolídeos, histórico de icterícia colestática associada, e uso com derivados do ergot."],"renal_adjustment":"Azitromicina: sem ajuste se ClCr > 10 mL/min. Claritromicina: reduzir dose em 50% se ClCr < 30 mL/min.","hepatic_adjustment":"Usar com precaução em insuficiência hepática moderada a grave.","adverse_reactions":["Distúrbios gastrointestinais (dor abdominal, cólicas, náuseas), diarreia, cefaleia e risco de prolongamento QTc."],"drug_interactions":["Claritromicina é potente inibidor de CYP3A4, aumentando níveis de estatinas, varfarina e carbamazepina."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
WHERE id = 4384;
UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Uso Clínico Geral","pharmacological_class":"Princípio Ativo Farmacêutico Padronizado","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"Dose individualizada conforme indicação médica","interval_text":"12/12 horas (ou a cada 24 horas conforme protocolo clínico)","route":"Via oral","duration_text":"Conforme prescrição médica e evolução clínica","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita Simples"}],"contraindications":["Hipersensibilidade grave ao princípio ativo ou aos componentes da fórmula.","Avaliar contraindicações específicas na gestação, lactação e insuficiência orgânica grave."],"renal_adjustment":"Avaliar taxa de filtração glomerular (TFG / ClCr). Ajustar dose ou intervalo em insuficiência renal moderada a grave conforme clearance.","hepatic_adjustment":"Usar com cautela em hepatopatias moderadas a graves; monitorar enzimas hepáticas periodicamente.","adverse_reactions":["Distúrbios gastrointestinais leves (náuseas, desconforto abdominal, dispepsia).","Cefaleia, tontura ou fadiga transitória.","Reações alérgicas cutâneas (erupção cutânea, prurido, urticária)."],"drug_interactions":["Monitorar associações com outros fármacos de metabolismo hepático (CYP450) ou eliminação renal concorrente.","Consultar interações específicas na presença de anticoagulantes ou depressores do sistema nervoso central."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
WHERE id = 2892;
UPDATE public.bulario_drugs 
