UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Oncologia e Hematologia / Imunologia Avançada","pharmacological_class":"Terapia-alvo / Inibidor de tirosina quinase ou anticorpo monoclonal","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"Dose individualizada conforme indicação médica","interval_text":"12/12 horas (ou a cada 24 horas conforme protocolo clínico)","route":"Via oral","duration_text":"Conforme prescrição médica e evolução clínica","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita de Controle Especial (Hospitalar / Oncologia)"}],"contraindications":["Hipersensibilidade grave, gravidez e lactação, e infecções graves ativas não controladas."],"renal_adjustment":"Ajustar dose conforme toxicidade hematológica/renal e clearance de creatinina descrito em protocolo oncológico.","hepatic_adjustment":"Monitorar transaminases e bilirrubina a cada ciclo; suspender ou reduzir dose em toxicidade hepática grau ≥ 3.","adverse_reactions":["Mielossupressão (neutropenia, anemia, plaquetopenia), fadiga, diarreia, rash cutâneo e risco de infecções oportunistas."],"drug_interactions":["Substratos e inibidores potentes de CYP3A4 podem alterar drasticamente as concentrações plasmáticas."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
