UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Cardiologia / Anti-hipertensivo e Antianginoso","pharmacological_class":"Betabloqueador adrenérgico","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"Dose inicial titulada conforme frequência cardíaca e pressão arterial","interval_text":"12/12 horas (ou 24/24 horas para formulações de liberação controlada/succinato)","route":"Via oral","duration_text":"Conforme prescrição médica e evolução clínica","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita Simples"}],"contraindications":["Bradicardia sinusal (< 50 bpm), bloqueio atrioventricular de 2º ou 3º grau, choque cardiogênico, asma brônquica grave."],"renal_adjustment":"Atenolol requer ajuste importante de dose no clearance reduzido; carvedilol e metoprolol não necessitam de ajuste renal.","hepatic_adjustment":"Metabolismo hepático intenso (carvedilol/metoprolol): contraindicado em insuficiência hepática grave.","adverse_reactions":["Bradicardia, hipotensão, fadiga, extremidades frias, broncoespasmo e mascaramento de sintomas de hipoglicemia."],"drug_interactions":["Monitorar associações com outros fármacos de metabolismo hepático (CYP450) ou eliminação renal concorrente.","Consultar interações específicas na presença de anticoagulantes ou depressores do sistema nervoso central."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
