UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Infectologia / Antibacteriano","pharmacological_class":"Betalactâmico / Penicilina","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"500 mg a 875 mg","interval_text":"8/8 horas (ou 12/12 horas para formulações de liberação prolongada / 875 mg)","route":"Via oral","duration_text":"7 a 10 dias","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita de Controle Especial (Antimicrobianos - 2 vias)"}],"contraindications":["Hipersensibilidade prévia imediata grave (anafilaxia, broncoespasmo) a penicilinas ou betalactâmicos."],"renal_adjustment":"ClCr 10–30 mL/min: administrar de 12/12 horas. ClCr < 10 mL/min: administrar de 24/24 horas.","hepatic_adjustment":"Geralmente seguro; monitorar função hepática se associado a clavulanato (risco de colestase).","adverse_reactions":["Diarreia, náuseas, rash cutâneo morbiliforme, urticária e candidíase secundária."],"drug_interactions":["Pode diminuir a eficácia de contraceptivos orais; alopurinol aumenta a incidência de rash."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
