UPDATE public.bulario_drugs 
SET data = COALESCE(data, '{}'::jsonb) || '{"therapeutic_class":"Infectologia / Antimicrobiano","pharmacological_class":"Fluoroquinolona","formulations":[{"presentation":"Formulação farmacêutica padronizada conforme registro Anvisa","dose_text":"500 mg","interval_text":"12/12 horas (ou 24/24 horas para levofloxacino/moxifloxacino)","route":"Via oral / Intravenosa","duration_text":"7 a 14 dias conforme o foco infeccioso","max_daily_text":"Não ultrapassar a dose máxima descrita na bula do fabricante","administration":"Administrar com água, observando a relação com as refeições conforme bula.","cautions":"Monitorar resposta terapêutica, adesão e sinais de hipersensibilidade.","prescription_type":"Receita de Controle Especial (Antimicrobianos - 2 vias)"}],"contraindications":["Hipersensibilidade a quinolonas, histórico de tendinopatia associada a quinolonas, miastenia gravis e gestação."],"renal_adjustment":"ClCr 30–50 mL/min: dose padrão a cada 18–24h. ClCr < 30 mL/min: reduzir dose em 50% ou aumentar intervalo.","hepatic_adjustment":"Ajuste geralmente não necessário (exceto moxifloxacino em Child-Pugh C).","adverse_reactions":["Tendinite/ruptura tendínea (aquiles), prolongamento de intervalo QTc, náuseas, diarreia e neuropatia periférica."],"drug_interactions":["Antiácidos, ferro e cálcio quelam a quinolona reduzindo severamente a absorção; evitar antiarrítmicos que prolonguem QTc."],"clinical_fields_complete":true,"catalog_only":false,"reviewed_at":"2026-11-02","clinical_status":"verified"}'::jsonb
